/** The shared verification cases (generated by conformance/generate.ts; replayed here and
 *  by the Rust runner, tests/vectors.rs). They pin what both implementations REFUSE and
 *  why — a document signed with another enrolled org's real key, a revoked or expired
 *  signer, an award that binds nothing determinate, a directory the root really signed
 *  but that is not well-formed — with the refusal REASON part of the expectation. */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { readFileSync } from "node:fs";
import { itarAttestationBlocker, verificationReport, type SigCheck } from "./authenticity.ts";
import { parseDirectoryJson, verifyDirectory, type Directory } from "./directory.ts";
import { recipientByOrg } from "./envelope.ts";
import { parsePrekeyBundleJson, verifyPrekeyBundle, type PrekeyBundle } from "./prekeys.ts";
import type { Quote, Traveler } from "./types.ts";

const load = <T>(name: string): T =>
  JSON.parse(
    readFileSync(new URL(`../../../conformance/signatures/${name}`, import.meta.url), "utf8"),
  ) as T;

type Trust = { root?: string; at_ms: number };
type ShapeCase = Trust & { name: string; text: string; directory: string; shape_ok: boolean; verifies: boolean };
type WantCheck = { ok: true; kid: string; org_id: string } | { ok: false; reason: string };
const dc = load<{
  root_public_key_hex: string;
  directories: Record<string, Directory>;
  directory_cases: ShapeCase[];
  bundle_cases: ShapeCase[];
  recipient_cases: (Trust & { name: string; directory: string; org_id: string; want: unknown })[];
}>("directory-cases.json");
const vc = load<{
  traveler_cases: (Trust & {
    name: string;
    traveler: string;
    directory: string;
    want: { authorship: WantCheck[]; award: WantCheck | null; quotes: unknown[]; verified: boolean };
  })[];
  itar_cases: (Trust & { name: string; traveler: string; quote: string; directory: string; want: string | null })[];
}>("verify-cases.json");

const rootOf = (c: Trust) => c.root ?? dc.root_public_key_hex;
const dirOf = (name: string): Directory => {
  const d = dc.directories[name];
  assert.ok(d, `case names an unknown directory: ${name}`);
  return d;
};
/** What a case pins about one check: who signed when it passes, why not when it does not. */
const slim = (c: SigCheck | undefined): WantCheck | null =>
  c === undefined ? null : c.ok ? { ok: true, kid: c.kid, org_id: c.org_id! } : { ok: false, reason: c.reason! };

describe("verification cases (shared with the Rust core)", () => {
  it("the case files are complete", () => {
    assert.ok(dc.directory_cases.length >= 35 && dc.bundle_cases.length >= 13, "directory-cases.json looks truncated");
    assert.ok(dc.recipient_cases.length >= 10, "recipient cases look truncated");
    assert.ok(vc.traveler_cases.length >= 30 && vc.itar_cases.length >= 12, "verify-cases.json looks truncated");
  });

  it("directories: well-formedness, then trust — a malformed directory never verifies, even root-signed", () => {
    for (const c of dc.directory_cases) {
      let shapeOk = true;
      let verifies = false;
      try {
        verifies = verifyDirectory(parseDirectoryJson(c.text), rootOf(c), new Date(c.at_ms));
      } catch {
        shapeOk = false;
      }
      assert.deepEqual({ shape_ok: shapeOk, verifies }, { shape_ok: c.shape_ok, verifies: c.verifies }, c.name);
      // …and not through the object entry point either (lenient JSON.parse, then verify).
      // Two cases are malformed only as TEXT — the value they parse to is a valid
      // directory — so they have no object form to refuse.
      const textOnly = c.name === "repeated-member" || c.name === "byte-order-mark";
      if (!c.shape_ok && !textOnly) {
        const lenient = JSON.parse(c.text) as Directory;
        assert.equal(verifyDirectory(lenient, rootOf(c), new Date(c.at_ms)), false, `${c.name} (object)`);
      }
    }
  });

  it("prekey bundles: well-formedness, then trust", () => {
    for (const c of dc.bundle_cases) {
      let shapeOk = true;
      let verifies = false;
      try {
        const bundle = parsePrekeyBundleJson(c.text);
        verifies = verifyPrekeyBundle(bundle, dirOf(c.directory), rootOf(c), new Date(c.at_ms)) !== undefined;
      } catch {
        shapeOk = false;
      }
      assert.deepEqual({ shape_ok: shapeOk, verifies }, { shape_ok: c.shape_ok, verifies: c.verifies }, c.name);
      // The object entry point enforces the same shape: a bundle the org really signed
      // but that is not well-formed must not verify when handed over already parsed.
      if (!c.shape_ok && c.name !== "repeated-member") {
        const lenient = JSON.parse(c.text) as PrekeyBundle;
        assert.equal(
          verifyPrekeyBundle(lenient, dirOf(c.directory), rootOf(c), new Date(c.at_ms)),
          undefined,
          `${c.name} (object)`,
        );
      }
    }
  });

  it("recipient resolution does not depend on the order of the directory's entries", () => {
    for (const c of dc.recipient_cases) {
      assert.deepEqual(recipientByOrg(dirOf(c.directory), c.org_id, new Date(c.at_ms)) ?? null, c.want, c.name);
    }
  });

  it("travelers: authorship, award and quote signatures — verdict AND reason", () => {
    for (const c of vc.traveler_cases) {
      const r = verificationReport(JSON.parse(c.traveler) as Traveler, dirOf(c.directory), rootOf(c), new Date(c.at_ms));
      assert.deepEqual(
        {
          authorship: r.authorship.map(slim),
          award: slim(r.award),
          quotes: r.quotes.map((q) => ({ quote_id: q.quote_id, check: slim(q.check) })),
          verified: r.verified,
        },
        c.want,
        c.name,
      );
    }
  });

  it("the ITAR gate: allowed, or refused for the stated reason", () => {
    for (const c of vc.itar_cases) {
      assert.equal(
        itarAttestationBlocker(
          JSON.parse(c.traveler) as Traveler,
          JSON.parse(c.quote) as Quote,
          dirOf(c.directory),
          rootOf(c),
          new Date(c.at_ms),
        ),
        c.want,
        c.name,
      );
    }
  });
});
